ALTER TABLE CFG_ACCOUNTS ADD COLUMN FAILED_SIGNINS BIGINT NOT NULL DEFAULT 0 CHECK (FAILED_SIGNINS>=0);
ALTER TABLE CFG_ACCOUNTS ADD COLUMN LOCKED_DATE TIMESTAMP WITH TIME ZONE;
ALTER TABLE CFG_ACCOUNTS ADD COLUMN MUST_CHANGE_PASSWORD VARCHAR(1) NOT NULL DEFAULT 'N' CHECK (MUST_CHANGE_PASSWORD IN ('Y','N'));
ALTER TABLE CFG_ACCOUNTS ADD COLUMN UI_SETTINGS JSONB NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(UI_SETTINGS)='object');
CREATE INDEX ix_project_health_runs_end ON AUD_PIPELINES_RUN_LOG (END_DATE,PIPELINE_ID) WHERE END_DATE IS NOT NULL;
CREATE INDEX ix_project_health_running ON AUD_PIPELINES_RUN_LOG (PIPELINE_ID) WHERE STATUS='IN-PROGRESS';
CREATE INDEX ix_project_health_queued_tasks ON AUD_TASK_ATTEMPTS (TASK_RUN_ID) WHERE STATUS='QUEUED';
CREATE INDEX ix_actions_catalog_success ON AUD_ACTIONS (PROJECT_ID,ACTION_ID DESC) WHERE COMMAND='generate-docs' AND OUTCOME='SUCCESS';
CREATE INDEX ix_actions_signin_success ON AUD_ACTIONS (ACTOR,ACTION_ID DESC) WHERE COMMAND='login' AND OUTCOME='SUCCESS';
